def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('kikar_708: no hunk on ' + rel)
    for a, b in HUNKS[rel]:
        if txt.count(a) != 1:
            raise SystemExit('kikar_708: FATAL anchor x%d in %s: %r' % (txt.count(a), rel, a[:60]))
        txt = txt.replace(a, b)
    print('[hunk] %s: %d hunk(s)' % (rel, len(HUNKS[rel])))
    return txt


def apply_main(txt):
    if txt.count(MAIN_LIST) != 1 or "'designer'" not in MAIN_LIST:
        raise SystemExit('kikar_708: FATAL: the live module list tail is not the one the previous release left')
    if txt.count(BUY) != 1 or txt.count("'buying-hub'") != 1:
        raise SystemExit('kikar_708: FATAL: buying-hub is not once before i18n in the live nadlan-config.php')
    print("[hunk] nadlan-config.php: no module change (proven)")
